// Dumps every read-only Scalable MCP tool's schema and output for the newest active connection.
import { writeFileSync } from "node:fs";
import { serviceDb } from "$W/lib/bank/server.ts";
import { withScalable } from "$W/lib/scalable/server.ts";

const READ = /^(get_|list_)/;
const SKIP = new Set(["get_security_chart", "get_security_news", "get_security_quote"]);
const { data } = await serviceDb().from("scalable_connections").select("id, workspace_id").eq("status", "active").order("created_at", { ascending: false }).limit(1).single();
if (!data) throw new Error("No active Scalable connection");
const out: Record<string, unknown> = {};
await withScalable(data.id, data.workspace_id, async mcp => {
  const tools = await mcp.listTools();
  out.tools = tools;
  const portfolios = await mcp.callTool("list_accessible_portfolios");
  out.list_accessible_portfolios = portfolios;
  const text = JSON.stringify(portfolios);
  const portfolioId = text.match(/"(?:portfolioId|portfolio_id|id)"\s*:\s*"([^"]+)"/)?.[1];
  for (const tool of tools as { name: string; inputSchema?: { required?: string[]; properties?: Record<string, unknown> } }[]) {
    if (!READ.test(tool.name) || SKIP.has(tool.name) || tool.name in out) continue;
    const required = tool.inputSchema?.required ?? [];
    const args: Record<string, unknown> = {};
    for (const name of required) if (/portfolio/i.test(name) && portfolioId) args[name] = portfolioId;
    if (required.some(name => !(name in args))) { out[tool.name] = { skipped: "needs", required }; continue; }
    try { out[tool.name] = { args, result: await mcp.callTool(tool.name, args) }; } catch (error) { out[tool.name] = { args, error: String(error) }; }
  }
  const tx = out.list_portfolio_transactions as { result?: unknown } | undefined;
  const txId = JSON.stringify(tx?.result ?? "").match(/"(?:transactionId|transaction_id|id)"\s*:\s*"([^"]+)"/)?.[1];
  if (txId) try { out.get_transaction_details_sample = await mcp.callTool("get_transaction_details", { ...(portfolioId ? { portfolioId } : {}), transactionId: txId }); } catch (error) { out.get_transaction_details_sample = String(error); }
});
writeFileSync("$S/scalable-probe.json", JSON.stringify(out, null, 2));
console.log("wrote", Object.keys(out).join(", "));
