async function stageBankImports(connectionId: string, workspaceId: string, psu?: PsuContext): Promise<{ imports: BankImport[]; error: string | null }> {
  "use step";
  const db = serviceDb();
  const connection = await db.from("bank_connections").select("status, valid_until").eq("id", connectionId).eq("workspace_id", workspaceId).single();
  if (connection.error) throw new Error(connection.error.message);
  if (connection.data.status !== "active") return { imports: [], error: null };
  if (Date.parse(connection.data.valid_until) <= Date.now()) {
    await db.from("bank_connections").update({ status: "expired", last_error: "Bank consent expired; reconnect to keep syncing" }).eq("id", connectionId);
    return { imports: [], error: null };
  }
  // Marks the sync as running for the UI until finishBankSync sets last_synced_at.
  const started = await db.from("bank_connections").update({ sync_started_at: new Date().toISOString() }).eq("id", connectionId).eq("workspace_id", workspaceId);
  if (started.error) throw new Error(started.error.message);
  const accounts = await db.from("bank_connection_accounts").select("provider_account_uid, currency_code, account_name, last_booked_on").eq("connection_id", connectionId);
  if (accounts.error) throw new Error(accounts.error.message);
  const settings = await loadWorkspaceSettings(db, workspaceId);
  const client = enableBankingClient();
  const today = isoDay(new Date());
  const imports: BankImport[] = [];
  try {
    for (const account of accounts.data) {
      const closing = preferredBalance(await client.balances(account.provider_account_uid, psu), account.currency_code);
      const transactions = await bookedSince(client, account.provider_account_uid, account.last_booked_on, today, psu);
      const statement = bankStatement(transactions, { accountName: account.account_name, currencyCode: account.currency_code, calendarTimezone: settings.timezone }, closing);
      if (!statement) continue;
      if (statement.rowCount > 10_000) throw new Error("Bank returned more than 10,000 transactions for one account");
      const bytes = Buffer.from(statement.csv, "utf8");
      const hash = createHash("sha256").update(bytes).digest("hex");
      const storagePath = `${workspaceId}/${hash}.csv`;
      const upload = await db.storage.from("imports").upload(storagePath, bytes, { contentType: "text/csv", upsert: false });
      if (upload.error && !/already exists|duplicate/i.test(upload.error.message)) throw new Error(upload.error.message);
      const inserted = await db.from("imports").insert({ workspace_id: workspaceId, filename: `${account.account_name} bank sync ${today}.csv`, storage_path: storagePath,
        file_hash: hash, status: "queued", mapping: statement.mapping, total_rows: statement.rowCount }).select("id").single();
      let importId = inserted.data?.id as string | undefined;
      if (inserted.error) {
        if (inserted.error.code !== "23505") throw new Error(inserted.error.message);
        // Identical window already imported: a no-op, unless an earlier attempt never ran it.
        const existing = await db.from("imports").select("id, status").eq("workspace_id", workspaceId).eq("file_hash", hash).neq("status", "undone").single();
        if (existing.error) throw new Error(existing.error.message);
        importId = existing.data.status === "queued" ? existing.data.id : undefined;
      }
      if (importId) imports.push({ importId, rowCount: statement.rowCount, uid: account.provider_account_uid, lastBookedOn: statement.lastBookedOn });
    }
    return { imports, error: null };
  } catch (error) {
    if (error instanceof EnableBankingError && error.expired) {
      await db.from("bank_connections").update({ status: "expired", last_error: "Bank consent expired; reconnect to keep syncing" }).eq("id", connectionId);
      return { imports, error: null };
    }
    // Rate limits (about 4 background fetches a day) and bank errors wait for the next run.
    const message = error instanceof EnableBankingError && error.rateLimited ? "The bank rate limit was reached; the next sync will retry" : String(error instanceof Error ? error.message : error);
    return { imports, error: message.slice(0, 1000) };
  }
}

async function finishBankSync(connectionId: string, workspaceId: string, imports: BankImport[], error: string | null) {
  "use step";
  const db = serviceDb();
  for (const item of imports) {
    const imported = await db.from("imports").select("status").eq("id", item.importId).eq("workspace_id", workspaceId).single();
    if (imported.error) throw new Error(imported.error.message);
    // Only advance the window once the rows are actually in; a failed import re-fetches next time.
    if (imported.data.status !== "completed") continue;
    const advanced = await db.from("bank_connection_accounts").update({ last_booked_on: item.lastBookedOn }).eq("connection_id", connectionId).eq("provider_account_uid", item.uid);
    if (advanced.error) throw new Error(advanced.error.message);
  }
  const done = await db.from("bank_connections").update({ last_synced_at: new Date().toISOString(), last_error: error }).eq("id", connectionId).eq("workspace_id", workspaceId);
  if (done.error) throw new Error(done.error.message);
}
import Papa from "papaparse";
import { parseCsv, validateImportConfirmation, type ImportMapping } from "@/lib/import/csv";
import type { BankBalance, BankTransaction } from "./enable-banking";

// A bank sync is an ordinary import: booked transactions become a canonical CSV with a
// fixed mapping, so dedupe, review, undo and source history work unchanged (issue #82).
const headers = ["id", "date", "description", "amount", "currency", "balance", "counterparty", "counterparty_iban"] as const;

const clip = (value: string, length: number) => Array.from(value.replace(/\s+/g, " ").trim()).slice(0, length).join("");

export function bankStatementRow(tx: BankTransaction) {
  const debit = tx.credit_debit_indicator === "DBIT";
  const magnitude = tx.transaction_amount.amount.replace(/^-/, "");
  // The indicator is the sign of record; without one, keep the amount's own sign.
  const amount = tx.credit_debit_indicator ? `${debit ? "-" : ""}${magnitude}` : tx.transaction_amount.amount;
  const counterparty = clip((debit ? tx.creditor?.name : tx.debtor?.name) ?? "", 200);
  const description = clip((tx.remittance_information ?? []).join(" "), 500) || counterparty || "Bank transaction";
  const balance = tx.balance_after_transaction?.currency === tx.transaction_amount.currency ? tx.balance_after_transaction.amount : "";
  return {
    id: clip(tx.entry_reference ?? tx.transaction_id ?? "", 500),
    date: tx.booking_date ?? tx.value_date ?? tx.transaction_date ?? "",
    description, amount, currency: tx.transaction_amount.currency, balance, counterparty,
    counterparty_iban: ((debit ? tx.creditor_account?.iban : tx.debtor_account?.iban) ?? "").replace(/\s/g, ""),
  } satisfies Record<(typeof headers)[number], string>;
}

// Deterministic bytes: the same bank data always hashes to the same import, so a repeated
// sync of an unchanged window is a no-op at the imports(file_hash) unique index.
// The closing balance rides on the latest booked row's balance column, so it lands in
// balance_snapshots with that import's provenance and undoes with it.
export function bankStatement(transactions: BankTransaction[], account: { accountName: string; currencyCode: string; calendarTimezone?: string }, closing?: BankBalance) {
  const byId = new Map<string, ReturnType<typeof bankStatementRow>>();
  const unidentified: ReturnType<typeof bankStatementRow>[] = [];
  for (const tx of transactions) {
    if (tx.status !== "BOOK") continue;
    const row = bankStatementRow(tx);
    if (!row.date) throw new Error("Booked bank transaction has no date");
    if (row.id) byId.set(row.id, row); else unidentified.push(row);
  }
  const rows = [...byId.values(), ...unidentified].sort((a, b) => a.date.localeCompare(b.date) || a.id.localeCompare(b.id)
    || a.amount.localeCompare(b.amount) || a.description.localeCompare(b.description));
  if (!rows.length) return null;
  const last = rows[rows.length - 1];
  if (closing && !last.balance && last.currency === account.currencyCode && closing.balance_amount.currency === account.currencyCode
    && (!closing.reference_date || closing.reference_date >= last.date)) last.balance = closing.balance_amount.amount;
  const csv = Papa.unparse({ fields: [...headers], data: rows.map(row => headers.map(header => row[header])) }, { newline: "\n" });
  const mapping: ImportMapping = {
    accountName: account.accountName, currencyCode: account.currencyCode,
    dateColumn: "date", descriptionColumn: "description", amountColumn: "amount", currencyColumn: "currency",
    balanceColumn: "balance", merchantColumn: "counterparty", externalIdColumn: "id",
    dateFormat: "iso", amountSign: "signed", numericConvention: "decimal-dot",
    ...(account.calendarTimezone ? { calendarTimezone: account.calendarTimezone } : {}),
  };
  const parsed = parseCsv(csv);
  return { csv, rowCount: parsed.length, lastBookedOn: last.date, mapping: validateImportConfirmation(parsed, mapping) };
}

// Booked balances first. Some banks (Revolut) publish only an available balance, so fall back to it.
// ponytail: an available balance can include an overdraft or credit line; exclude per bank if that bites.
export function preferredBalance(balances: BankBalance[], currencyCode: string) {
  const order = ["CLBD", "ITBD", "XPCD", "CLAV", "ITAV"];
  const usable = balances.filter(balance => balance.balance_amount.currency === currencyCode && order.includes(balance.balance_type));
  return usable.sort((a, b) => order.indexOf(a.balance_type) - order.indexOf(b.balance_type))[0];
}

